  ) v(fonte, tipo, dsei, codigo, nome, municipio, motivo_tipo, motivo, candidatos)
on conflict on constraint "UK_PENDCOORD_PONTO" do nothing;
-- ═══ CORPO DA CARGA (fim) ═══

-- C1. Contagens.
do $$
declare
  v_polo integer;
  v_u integer;
begin
  select count(*) filter (where "TP_PONTO" = 'polo'), count(*) filter (where "TP_PONTO" = 'u')
    into v_polo, v_u from private."TB_PENDENCIA_COORDENADA_MAPA";
  if v_polo < 92 or v_u < 156 then
    raise exception 'FALHOU C1: esperava 92 polos e 156 UBSI, achou % e %', v_polo, v_u;
  end if;
  if exists (select 1 from private."TB_PENDENCIA_COORDENADA_MAPA" where "ST_CONFERIDO" <> 'N') then
    raise exception 'FALHOU C1: pendência nasceu conferida';
  end if;
  raise notice 'ok C1: % polos e % UBSI pendentes', v_polo, v_u;
end;
$$;

-- C2. Cada pendência acha o ponto na fonte (pelo código; nome diferente só avisa).
do $$
declare
  v_sem text;
  v_nome integer;
begin
  with pontos as (
    select 'lmap'::text fonte, 'polo'::text tipo, d.value ->> 'k' dsei, p.value ->> 'cod' codigo, p.value ->> 'n' nome
      from public."TB_CONFIG_MAPA_SAUDE_INDIG" c,
           jsonb_array_elements(c.payload -> 'dsei') d,
           jsonb_array_elements(coalesce(d.value -> 'polos', '[]'::jsonb)) p
     where c.chave = 'lmap'
    union all
    select 'rede_cnes', t.tipo, r.key, u.value ->> 1, u.value ->> 0
      from public."TB_CONFIG_MAPA_SAUDE_INDIG" c,
           jsonb_each(c.payload -> 'rede') r,
           unnest(array['u', 'c']) t(tipo),
           jsonb_array_elements(coalesce(r.value -> t.tipo, '[]'::jsonb)) u
     where c.chave = 'rede_cnes'
  )
  select string_agg(format('%s/%s/%s/%s', p."TP_FONTE", p."NO_DSEI", p."CO_PONTO", p."NO_PONTO"), '; ')
    into v_sem
    from (select * from private."TB_PENDENCIA_COORDENADA_MAPA" x
           where not exists (select 1 from pontos o where o.fonte = x."TP_FONTE" and o.tipo = x."TP_PONTO"
                               and o.dsei = x."NO_DSEI" and o.codigo = x."CO_PONTO")
           limit 10) p;
  if v_sem is not null then
    raise exception 'FALHOU C2: pendência sem ponto na fonte: %', v_sem;
  end if;
  select count(*) into v_nome
    from private."TB_PENDENCIA_COORDENADA_MAPA" x
   where not exists (select 1 from pontos o where o.fonte = x."TP_FONTE" and o.tipo = x."TP_PONTO"
                       and o.dsei = x."NO_DSEI" and o.codigo = x."CO_PONTO" and o.nome = x."NO_PONTO");
  if v_nome > 0 then
    raise notice 'aviso C2: % pendências com nome diferente do da fonte (a fila mostra o da fonte)', v_nome;
  end if;
  raise notice 'ok C2: toda pendência acha o seu ponto';
end;
$$;

-- C3. Candidatos: formato e limites do Brasil.
do $$
declare
  v_ruins integer;
  v_total integer;
begin
  select count(*) filter (where not (c.value ? 'f' and c.value ? 'n'
                                     and (c.value ->> 'lat')::double precision between -34.9 and 6.4
                                     and (c.value ->> 'lon')::double precision between -74.2 and -32)),
         count(*)
    into v_ruins, v_total
    from private."TB_PENDENCIA_COORDENADA_MAPA" p, jsonb_array_elements(p."DS_CANDIDATO") c;
  if v_ruins > 0 then raise exception 'FALHOU C3: % candidatos fora do formato ou do Brasil', v_ruins; end if;
  if v_total < 566 then raise exception 'FALHOU C3: esperava 566 candidatos, achou %', v_total; end if;
  raise notice 'ok C3: % candidatos no formato e no Brasil', v_total;
  raise notice 'ENSAIO OK';
end;
$$;

select "TP_PONTO" as tipo, count(*) as pendencias,
       sum(jsonb_array_length("DS_CANDIDATO")) as candidatos,
       count(*) filter (where jsonb_array_length("DS_CANDIDATO") = 0) as sem_candidato
  from private."TB_PENDENCIA_COORDENADA_MAPA"
 group by "TP_PONTO"
 order by "TP_PONTO";

rollback;
